const CONFIG = { centTolerance: 0.05, dateWindowDays: 3 };
function round2(n) { return Math.round(n * 100) / 100; }
function daysBetween(a, b) { return Math.abs((new Date(a).getTime() - new Date(b).getTime()) / 86400000); }

// --- normalize both sources to one schema, dedupe by id (idempotency) ---
const platformRaw = $('Extract Platform Rows').all().map(function (i) { return i.json; });
const bankRaw = $('Extract Bank Rows').all().map(function (i) { return i.json; });

const seenIds = new Set();
const platform = [];
for (const r of platformRaw) {
  const id = String(r.id || '').trim();
  if (!id || seenIds.has(id)) continue; // reprocessing the same file duplicates nothing
  seenIds.add(id);
  platform.push({ id: id, date: String(r.date || ''), type: String(r.type || '').toLowerCase(), amount: Number(r.amount) || 0, fee: Number(r.fee) || 0, ref: String(r.ref || '') });
}
const seenBank = new Set();
const bank = [];
for (const r of bankRaw) {
  const key = String(r.date) + '|' + String(r.amount) + '|' + String(r.description);
  if (seenBank.has(key)) continue;
  seenBank.add(key);
  bank.push({ date: String(r.date || ''), amount: Number(r.amount) || 0, description: String(r.description || '') });
}

// refunds stay as their own signed lines; payouts are the aggregation records
const txns = platform.filter(function (t) { return t.type !== 'payout'; });
const payouts = platform.filter(function (t) { return t.type === 'payout'; });

// settlement batches: the set of transactions that compose one deposit
const batches = {};
for (const t of txns) { if (!batches[t.date]) batches[t.date] = []; batches[t.date].push(t); }
function batchNet(d) { return round2(batches[d].reduce(function (s, t) { return s + t.amount - t.fee; }, 0)); }

const rows = [];
function push(tab, fields) { rows.push({ json: Object.assign({ tab: tab }, fields) }); }

const usedBatches = new Set();
const matchedPayoutRefs = new Set();

for (const dep of bank) {
  // tier 1: exact reference
  let payout = payouts.find(function (p) { return p.ref && dep.description.indexOf(p.ref) !== -1; });
  let criterion = payout ? 'exact_reference' : null;
  // tier 2: amount match inside the date window
  if (!payout) {
    payout = payouts.find(function (p) { return !matchedPayoutRefs.has(p.ref) && Math.abs(p.amount - dep.amount) < 0.005 && daysBetween(p.date, dep.date) <= CONFIG.dateWindowDays; });
    if (payout) criterion = 'amount_in_date_window';
  }
  // tier 3: amount within the configured cent tolerance
  if (!payout) {
    payout = payouts.find(function (p) { return !matchedPayoutRefs.has(p.ref) && Math.abs(p.amount - dep.amount) <= CONFIG.centTolerance; });
    if (payout) criterion = 'amount_cent_tolerance';
  }
  if (!payout) {
    push('Differences', { date: dep.date, kind: 'bank_deposit', reference: dep.description, amount: dep.amount, reason: 'no_platform_counterpart', criterion: '', delta: '', detail: 'no platform payout matches this deposit' });
    continue;
  }
  matchedPayoutRefs.add(payout.ref);

  // --- disaggregation: open the deposit against the batch that composes it ---
  let best = null;
  let bestDelta = Infinity;
  for (const d of Object.keys(batches)) {
    if (usedBatches.has(d)) continue;
    const delta = Math.abs(batchNet(d) - dep.amount);
    if (delta < bestDelta) { bestDelta = delta; best = d; }
  }
  if (best === null) {
    push('Differences', { date: dep.date, kind: 'bank_deposit', reference: dep.description, amount: dep.amount, reason: 'no_platform_counterpart', criterion: criterion, delta: '', detail: 'no settlement batch left to compose this deposit' });
    continue;
  }
  usedBatches.add(best);
  const comp = batches[best];
  const net = batchNet(best);
  const withinAmount = bestDelta <= CONFIG.centTolerance;
  const lagDays = round2(daysBetween(best, dep.date));
  const withinWindow = lagDays <= CONFIG.dateWindowDays;

  if (withinAmount && withinWindow) {
    push('Reconciled', { date: dep.date, kind: 'bank_deposit', reference: dep.description, amount: dep.amount, matched_to: 'batch ' + best + ' (' + comp.length + ' transactions)', criterion: criterion, delta: round2(bestDelta) });
    for (const t of comp) {
      push('Reconciled', { date: t.date, kind: t.type, reference: t.id, amount: round2(t.amount - t.fee), matched_to: dep.description, criterion: criterion, delta: 0 });
    }
  } else {
    const reasons = [];
    if (!withinAmount) reasons.push('amount_difference');
    if (!withinWindow) reasons.push('outside_window');
    push('Differences', { date: dep.date, kind: 'bank_deposit', reference: dep.description, amount: dep.amount, reason: reasons.join('+'), criterion: criterion, delta: round2(net - dep.amount), detail: 'batch ' + best + ' nets ' + net + ', deposit is ' + dep.amount + ', lag ' + lagDays + ' days' });
    for (const t of comp) {
      push('Pending', { date: t.date, kind: t.type, reference: t.id, amount: round2(t.amount - t.fee), matched_to: dep.description, reason: 'deposit flagged: ' + reasons.join('+') });
    }
  }
}

// platform payouts that never landed in the bank
for (const p of payouts) {
  if (!matchedPayoutRefs.has(p.ref)) {
    push('Differences', { date: p.date, kind: 'platform_payout', reference: p.ref, amount: p.amount, reason: 'no_bank_counterpart', criterion: '', delta: '', detail: 'payout never appeared in the bank statement' });
  }
}
// settlement batches never tied to any deposit
for (const d of Object.keys(batches)) {
  if (usedBatches.has(d)) continue;
  for (const t of batches[d]) {
    push('Pending', { date: t.date, kind: t.type, reference: t.id, amount: round2(t.amount - t.fee), matched_to: '', reason: 'no deposit composed from this settlement batch' });
  }
}
return rows;

const rows = $input.all().map(function (i) { return i.json; });
const deposits = rows.filter(function (r) { return r.kind === 'bank_deposit'; });
const reconciled = deposits.filter(function (r) { return r.tab === 'Reconciled'; });
const differences = rows.filter(function (r) { return r.tab === 'Differences'; });
const pending = rows.filter(function (r) { return r.tab === 'Pending'; });
function sum(list) { return Math.round(list.reduce(function (s, r) { return s + (Number(r.amount) || 0); }, 0) * 100) / 100; }
let largest = null;
for (const d of differences) {
  const delta = Math.abs(Number(d.delta) || 0);
  if (!largest || delta > Math.abs(Number(largest.delta) || 0)) largest = d;
}
const lines = [
  'Payout reconciliation finished.',
  '',
  'Reconciled deposits: ' + reconciled.length + ' (total ' + sum(reconciled) + ')',
  'Flagged in Differences: ' + differences.length,
  'Transactions left Pending: ' + pending.length + ' (total ' + sum(pending) + ')',
  ''
];
if (largest) {
  lines.push('Largest difference: ' + largest.reference + ' — ' + largest.reason + (largest.delta !== '' ? ' (delta ' + largest.delta + ')' : ''));
}
return [{ json: { subject: 'Reconciliation: ' + reconciled.length + ' deposits ok, ' + differences.length + ' flagged', body: lines.join('\n') } }];
